    {
        $order = Order::place(OrderId::generate(), CustomerId::generate());
        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 3, new Money(300_00, Currency::CZK));
        $order->confirm();
        $order->markPaid();
        self::getContainer()->get(OrderRepository::class)->save($order);

        return $order;
    }
}
